#pragma once

#include "cler_scheduler_config.hpp"
#include "detail/cler_partition.hpp"
#include "detail/cler_park.hpp"
#include "detail/cler_barrier.hpp"
#include "../task_policies/cler_task_policy_base.hpp"
#include <algorithm>
#include <array>
