#include <cstdint>

namespace cler {
    namespace sched {

        template<typename Host>
        struct PinnedIslandsScheduler {
            using TaskPolicy = typename Host::TaskPolicyType;
            using Partition = typename Host::PartitionType;
            using ParkGroup = sched::detail::ParkGroup<TaskPolicy, DEFAULT_MAX_WORKERS>;
            using WorkerParkState = typename ParkGroup::WorkerParkState;
            using RepartitionBarrier = sched::detail::RepartitionBarrier<TaskPolicy>;

            static constexpr size_t CALIBRATION_DEADLINE_CHECK_PASSES = 256;
            static constexpr size_t kLeaderWorker = 0;

            struct State {
                detail::WorkerQueueScheduler<Host::block_count, DEFAULT_MAX_WORKERS> queues;
                ParkGroup park_states;
                Partition partition;
                RepartitionBarrier barrier;
                std::chrono::steady_clock::time_point calibration_deadline;
                std::chrono::steady_clock::time_point next_repartition_check;
                size_t pinned_worker_count = 0;

                void reset() {
                    park_states.reset();
                    partition = Partition{};
                    barrier.reset();
                    pinned_worker_count = 0;
                }
            };

            struct WakePinnedWorkers {
                State* state;
                void operator()() const {
                    state->park_states.wake_others(detail::kNoWorker, state->pinned_worker_count);
                }
            };

            static void start(Host host, State& state, const FlowGraphConfig& config) {
                host.reset_stop_flag();
                host.prepare_run();

                if (config.collect_detailed_stats) {
                    host.mark_block_start_times();
                }

                host.warn_unresolved_edges();

                std::array<uint8_t, Host::block_count> regular_ids{};
                const size_t regular_count = host.collect_regular_blocks(regular_ids);

                state.calibration_deadline = std::chrono::steady_clock::now() +
                                             std::chrono::milliseconds(config.pinned_islands.calibration_ms);
                state.next_repartition_check = state.calibration_deadline;

                const size_t max_worker_count = (std::min)(DEFAULT_MAX_WORKERS, regular_count);
                const size_t requested_workers = config.pinned_islands.island_count != 0
                    ? config.pinned_islands.island_count
                    : config.num_workers;
                state.pinned_worker_count = regular_count == 0
                    ? 0
                    : (std::max)(size_t{1}, (std::min)(requested_workers, max_worker_count));

                host.launch_may_block_tasks_sampled(config, WakePinnedWorkers{&state});

                if (regular_count == 0) return;

                host.mark_item_counters();
                host.rebuild_partition(state.pinned_worker_count, false, state.partition);
                state.queues.initialize_islands(state.partition.block_ids.data(),
                                                state.partition.island_begin.data(),
                                                state.partition.island_count);

                State* state_ptr = &state;
                for (size_t worker_id = 0; worker_id < state.pinned_worker_count; ++worker_id) {
                    host.add_task([host, state_ptr, worker_id, config]() {
                        worker_loop(host, *state_ptr, worker_id, config);
                    });
                }
            }

            static void notify_stop(Host, State& state) {
                state.park_states.wake_all();
                state.barrier.bump_epoch_and_unpark();
            }

        private:
            static void worker_loop(Host host, State& state, size_t worker_id, const FlowGraphConfig& config) {
                TaskPolicy::configure_thread_for_low_latency_sleep();
                if (!TaskPolicy::pin_to_core(config.pinned_islands.cpu_id_offset + worker_id)) {
                    host.note_affinity_failure();
                }

                WorkerParkState& park_state = state.park_states[worker_id];
                BackoffState backoff_state{};
                size_t zero_progress_passes = 0;
                size_t passes_since_deadline_check = 0;
                bool park_armed = false;
                bool pass_follows_park = false;
                uint32_t observed_sleep_epoch = 0;

                while (!host.stop_requested()) {
                    state.queues.reset_pass(worker_id);
                    bool did_work_in_pass = false;
                    size_t block_idx;

                    while (state.queues.get_next_block(worker_id, block_idx)) {
                        if (host.stop_requested()) break;

                        auto t_before = config.collect_detailed_stats
                            ? std::chrono::high_resolution_clock::now()
                            : std::chrono::high_resolution_clock::time_point{};

                        bool block_did_work = host.execute_block_sampled(block_idx, config);

                        if (!block_did_work && config.collect_detailed_stats) {
                            auto t_after = std::chrono::high_resolution_clock::now();
                            std::chrono::duration<double> dt = t_after - t_before;
                            host.add_block_dead_time(block_idx, dt.count());
                        }

                        did_work_in_pass = did_work_in_pass || block_did_work;
                    }

                    const bool deadline_check_due =
                        ++passes_since_deadline_check >= CALIBRATION_DEADLINE_CHECK_PASSES || pass_follows_park;
                    pass_follows_park = false;

                    if (worker_id == kLeaderWorker && deadline_check_due && !state.barrier.has_request()) {
                        passes_since_deadline_check = 0;
                        if (leader_should_repartition(host, state, config)) {
                            state.barrier.request_current_epoch();
                            state.park_states.wake_others(worker_id, state.pinned_worker_count);
                        }
                    }

                    const uint32_t requested_generation = state.barrier.requested_generation();
                    if (requested_generation != RepartitionBarrier::kNoRequest) {
                        if (park_armed) {
                            park_armed = false;
                            park_state.parked.store(false, std::memory_order_relaxed);
                        }
                        repartition_barrier(host, state, worker_id, requested_generation, config);
                        zero_progress_passes = 0;
                        TaskPolicy::backoff_reset(backoff_state);
                        continue;
                    }

                    if (did_work_in_pass) {
                        zero_progress_passes = 0;
                        park_armed = false;
                        if (park_state.parked.load(std::memory_order_relaxed)) {
                            park_state.parked.store(false, std::memory_order_relaxed);
                        }
                        TaskPolicy::backoff_reset(backoff_state);
                        state.park_states.wake_others(worker_id, state.pinned_worker_count);
                        continue;
                    }

                    ++zero_progress_passes;

                    if (zero_progress_passes <= config.pinned_islands.park_after_zero_passes) {
                        TaskPolicy::backoff(backoff_state);
                    } else if (!park_armed) {
                        park_armed = true;
                        observed_sleep_epoch = park_state.sleep_epoch.load(std::memory_order_acquire);
                        park_state.parked.store(true, std::memory_order_release);
                    } else {
                        park_state.park_events.fetch_add(1, std::memory_order_relaxed);
                        TaskPolicy::park(park_state.sleep_epoch, observed_sleep_epoch);
                        park_armed = false;
                        pass_follows_park = true;
                        park_state.parked.store(false, std::memory_order_relaxed);
                    }
                }

                park_state.parked.store(false, std::memory_order_relaxed);

                if (config.collect_detailed_stats) {
                    for (size_t i = 0; i < Host::block_count; ++i) {
                        if (state.queues.is_block_owner(worker_id, i)) {
                            host.set_block_runtime_from_start(i);
                        }
                    }
                }
            }

            static bool leader_should_repartition(Host host, State& state, const FlowGraphConfig& config) {
                if (config.pinned_islands.island_count != 0) return false;

                const bool calibrated = state.barrier.count() != 0;
                if (calibrated && config.pinned_islands.repartition_check_ms == 0) return false;

                const auto now = std::chrono::steady_clock::now();
                if (!calibrated) return now >= state.calibration_deadline;
                if (now < state.next_repartition_check) return false;
                state.next_repartition_check = now + std::chrono::milliseconds(config.pinned_islands.repartition_check_ms);

                std::array<double, Host::block_count> weights{};
                host.collect_block_weights(state.partition, weights);

                Partition candidate;
                host.rebuild_partition(state.pinned_worker_count, true, candidate);

                return sched::detail::max_island_weight(candidate, weights) <
                       sched::detail::REPARTITION_IMPROVEMENT_RATIO * sched::detail::max_island_weight(state.partition, weights);
            }

            static void repartition_barrier(Host host, State& state, size_t worker_id, uint32_t generation,
                                            const FlowGraphConfig& config) {
                state.barrier.arrive(
                    worker_id == kLeaderWorker, generation, state.pinned_worker_count,
                    [host]() { return host.stop_requested(); },
                    [&state, worker_id]() { state.park_states.wake_others(worker_id, state.pinned_worker_count); },
                    [host, &state, &config]() mutable {
                        host.rebuild_partition(state.pinned_worker_count, true, state.partition);
                        host.mark_item_counters();
                        state.queues.initialize_islands(state.partition.block_ids.data(),
                                                state.partition.island_begin.data(),
                                                state.partition.island_count);
                        state.next_repartition_check = std::chrono::steady_clock::now() +
                                                       std::chrono::milliseconds(config.pinned_islands.repartition_check_ms);
                    });
            }
        };

    }
}

include/schedulers/detail/cler_barrier.h:
#pragma once

#include "../cler_scheduler_config.hpp"
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <limits>

namespace cler {
    namespace sched {
    namespace detail {

        template<typename TaskPolicy>
        class RepartitionBarrier {
        public:
            static constexpr uint32_t kNoRequest = (std::numeric_limits<uint32_t>::max)();

            void reset() {
                _partition_epoch.store(0, std::memory_order_relaxed);
                _request.store(kNoRequest, std::memory_order_relaxed);
                _barrier.store(barrier_word(0, 0), std::memory_order_relaxed);
                _count.store(0, std::memory_order_relaxed);
            }

            size_t count() const { return _count.load(std::memory_order_acquire); }

            uint32_t current_epoch() const { return _partition_epoch.load(std::memory_order_relaxed); }

            uint32_t requested_generation() const { return _request.load(std::memory_order_relaxed); }

            bool has_request() const { return requested_generation() != kNoRequest; }

            void request_current_epoch() {
                _request.store(_partition_epoch.load(std::memory_order_relaxed),
                               std::memory_order_release);
            }

            void bump_epoch_and_unpark() {
                _partition_epoch.fetch_add(1, std::memory_order_release);
                TaskPolicy::unpark(_partition_epoch);
            }

            template<typename StopRequested, typename WakeOthers, typename Repartition>
            void arrive(bool is_leader, uint32_t generation, size_t worker_count,
                        StopRequested stop_requested, WakeOthers wake_others,
                        Repartition repartition) {
                if (!arrive_at_barrier(generation)) return;

                if (!is_leader) {
                    while (_partition_epoch.load(std::memory_order_acquire) == generation &&
                           !stop_requested()) {
                        TaskPolicy::park(_partition_epoch, generation);
                    }
                    return;
                }

                while (barrier_arrived(_barrier.load(std::memory_order_acquire)) < worker_count &&
                       !stop_requested()) {
                    wake_others();
                    TaskPolicy::yield();
                }

                if (!stop_requested()) {
                    repartition();
                    _count.fetch_add(1, std::memory_order_relaxed);
                }

                _barrier.store(barrier_word(generation + 1, 0), std::memory_order_release);
                _request.store(kNoRequest, std::memory_order_release);
                _partition_epoch.fetch_add(1, std::memory_order_release);
                TaskPolicy::unpark(_partition_epoch);
            }

        private:
            static constexpr uint64_t barrier_word(uint32_t generation, uint32_t arrived) {
                return (static_cast<uint64_t>(generation) << 32) | arrived;
            }
            static constexpr uint32_t barrier_generation(uint64_t word) {
                return static_cast<uint32_t>(word >> 32);
            }
            static constexpr uint32_t barrier_arrived(uint64_t word) {
                return static_cast<uint32_t>(word);
            }

            bool arrive_at_barrier(uint32_t generation) {
                uint64_t word = _barrier.load(std::memory_order_acquire);
                while (barrier_generation(word) == generation) {
                    if (_barrier.compare_exchange_weak(word, word + 1,
                                                       std::memory_order_acq_rel,
                                                       std::memory_order_acquire)) {
                        return true;
                    }
                }
                return false;
            }

            std::atomic<uint32_t> _partition_epoch{0};
            std::atomic<uint32_t> _request{kNoRequest};
            std::atomic<uint64_t> _barrier{0};
            std::atomic<size_t> _count{0};
        };

    }
    }
}

include/schedulers/detail/cler_park.hpp:
#pragma once

#include "../cler_scheduler_config.hpp"
#include "../../cler_platform.hpp"
#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <limits>

namespace cler {
    namespace sched {
    namespace detail {

        static constexpr size_t kNoWorker = (std::numeric_limits<size_t>::max)();

        template<typename TaskPolicy, size_t MaxWorkers>
        class ParkGroup {
        public:
            struct alignas(platform::cache_line_size) WorkerParkState {
                std::atomic<uint32_t> sleep_epoch{0};
                std::atomic<bool> parked{false};
                std::atomic<uint64_t> park_events{0};
            };

            WorkerParkState& operator[](size_t worker_id) { return _states[worker_id]; }
            const WorkerParkState& operator[](size_t worker_id) const { return _states[worker_id]; }

            void reset() {
                for (auto& state : _states) {
                    state.sleep_epoch.store(0, std::memory_order_relaxed);
                    state.parked.store(false, std::memory_order_relaxed);
                    state.park_events.store(0, std::memory_order_relaxed);
                }
            }

            void wake_others(size_t self_id, size_t worker_count) {
                for (size_t w = 0; w < worker_count; ++w) {
                    if (w == self_id) continue;
                    WorkerParkState& state = _states[w];
                    if (!state.parked.load(std::memory_order_relaxed)) continue;
                    if (!state.parked.exchange(false, std::memory_order_acq_rel)) continue;
                    state.sleep_epoch.fetch_add(1, std::memory_order_release);
                    TaskPolicy::unpark(state.sleep_epoch);
                }
            }

            void wake_all() {
                for (auto& state : _states) {
                    state.parked.store(false, std::memory_order_relaxed);
                    state.sleep_epoch.fetch_add(1, std::memory_order_release);
                    TaskPolicy::unpark(state.sleep_epoch);
                }
            }

            uint64_t total_park_events() const {
                uint64_t total = 0;
                for (const auto& state : _states) {
                    total += state.park_events.load(std::memory_order_relaxed);
                }
                return total;
            }

        private:
            std::array<WorkerParkState, MaxWorkers> _states;
        };

    }
    }
}

include/schedulers/detail/cler_partition:
#pragma once

#include "cler_topology.hpp"
#include "../cler_scheduler_config.hpp"
#include "../../cler_platform.hpp"
#include <array>
#include <algorithm>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <limits>

namespace cler {


    namespace sched {
    namespace detail {

        static constexpr size_t COST_SAMPLE_PERIOD_CALLS = 61;
        static constexpr double CROSS_EDGE_PENALTY_NS = 200.0;
        static constexpr double REPARTITION_IMPROVEMENT_RATIO = 0.8;

        inline uint64_t double_to_bits(double value) {
            uint64_t bits;
            std::memcpy(&bits, &value, sizeof(bits));
            return bits;
        }

        inline double bits_to_double(uint64_t bits) {
            double value;
            std::memcpy(&value, &bits, sizeof(value));
            return value;
        }

        struct alignas(platform::cache_line_size) SchedulerCostSample {
            size_t calls_until_sample = COST_SAMPLE_PERIOD_CALLS;
            std::atomic<uint64_t> ewma_ns_per_call_bits{0};
            std::atomic<uint64_t> ewma_items_per_call_bits{0};
        };


        inline double ns_per_item(const SchedulerCostSample& sample) {
            const double ns = bits_to_double(sample.ewma_ns_per_call_bits.load(std::memory_order_relaxed));
            const double items = bits_to_double(sample.ewma_items_per_call_bits.load(std::memory_order_relaxed));
            return ns > 0.0 ? ns / (std::max)(items, 1.0) : 0.0;
        }

        template<size_t MaxBlocks>
        void collect_cost_weights(const std::array<SchedulerCostSample, MaxBlocks>& samples,
                                  const std::array<uint8_t, MaxBlocks>& order, size_t count,
                                  std::array<double, MaxBlocks>& weights) {
            for (size_t i = 0; i < count; ++i) {
                const uint8_t id = order[i];
                weights[id] = ns_per_item(samples[id]);
            }
        }

        template<size_t MaxBlocks>
        void fill_unsampled_with_median(const std::array<uint8_t, MaxBlocks>& order, size_t count,
                                        std::array<double, MaxBlocks>& weights) {
            std::array<double, MaxBlocks> sorted{};
            size_t sampled = 0;
            for (size_t i = 0; i < count; ++i) {
                if (weights[order[i]] > 0.0) sorted[sampled++] = weights[order[i]];
            }

            double median = 1.0;
            if (sampled > 0) {
                std::sort(sorted.begin(), sorted.begin() + sampled);
                median = sorted[sampled / 2];
            }
            for (size_t i = 0; i < count; ++i) {
                if (weights[order[i]] <= 0.0) weights[order[i]] = median;
            }
        }

        template<size_t MaxBlocks, size_t MaxWorkers>
        double max_island_weight(const Partition<MaxBlocks, MaxWorkers>& partition,
                                 const std::array<double, MaxBlocks>& weights) {
            double worst = 0.0;
            for (size_t w = 0; w < partition.island_count; ++w) {
                double island = 0.0;
                for (uint16_t k = partition.island_begin[w]; k < partition.island_begin[w + 1]; ++k) {
                    island += weights[partition.block_ids[k]];
                }
                worst = (std::max)(worst, island);
            }
            return worst;
        }

        template<size_t MaxBlocks, size_t MaxWorkers>
        bool build_partition(const Edge* edges, size_t edge_count,
                             const std::array<double, MaxBlocks>& block_weights,
                             const std::array<uint8_t, MaxBlocks>& regular_ids, size_t regular_count,
                             size_t worker_count, bool use_costs, bool topology_is_complete,
                             Partition<MaxBlocks, MaxWorkers>& out) {
            std::array<uint8_t, MaxBlocks> order{};
            if (topology_is_complete) {
                topo_sort_blocks<MaxBlocks>(edges, edge_count, regular_ids.data(), regular_count, order);
            } else {
                order = regular_ids;
            }

            const size_t islands = (std::max)(size_t{1}, (std::min)(worker_count, regular_count));
            out.block_ids = order;
            out.block_count = static_cast<uint16_t>(regular_count);
            out.island_count = static_cast<uint16_t>(islands);

            if (!use_costs || !topology_is_complete) {
                size_t cursor = 0;
                for (size_t w = 0; w < islands; ++w) {
                    out.island_begin[w] = static_cast<uint16_t>(cursor);
                    cursor += regular_count / islands + (w < regular_count % islands ? 1 : 0);
                }
                out.island_begin[islands] = static_cast<uint16_t>(regular_count);
                return true;
            }

            std::array<double, MaxBlocks> weights = block_weights;
            fill_unsampled_with_median<MaxBlocks>(order, regular_count, weights);

            std::array<double, MaxBlocks + 1> prefix{};
            for (size_t i = 0; i < regular_count; ++i) prefix[i + 1] = prefix[i] + weights[order[i]];


            std::array<uint16_t, MaxBlocks> crossings{};
            count_cut_crossings<MaxBlocks>(edges, edge_count, order, regular_count, crossings);

            std::array<double, MaxBlocks + 1> prev_max{};
            std::array<double, MaxBlocks + 1> prev_crossings{};
            std::array<double, MaxBlocks + 1> island_max{};
            std::array<double, MaxBlocks + 1> total_crossings{};
            std::array<std::array<uint16_t, MaxBlocks + 1>, MaxWorkers + 1> choice{};

            const double infinity = (std::numeric_limits<double>::max)();
            for (size_t end = 0; end <= regular_count; ++end) {
                prev_max[end] = (end == 0) ? 0.0 : infinity;
                prev_crossings[end] = 0.0;
            }

            for (size_t k = 1; k <= islands; ++k) {
                for (size_t end = 0; end <= regular_count; ++end) island_max[end] = infinity;
                for (size_t end = k; end <= regular_count - (islands - k); ++end) {
                    double best_objective = infinity;
                    for (size_t start = k - 1; start < end; ++start) {
                        if (prev_max[start] == infinity) continue;
                        const double candidate_max = (std::max)(prev_max[start], prefix[end] - prefix[start]);
                        const double candidate_crossings = prev_crossings[start] + (start > 0 ? crossings[start] : 0);
                        const double objective = candidate_max + CROSS_EDGE_PENALTY_NS * candidate_crossings;
                        if (objective < best_objective) {
                            best_objective = objective;
                            island_max[end] = candidate_max;
                            total_crossings[end] = candidate_crossings;
                            choice[k][end] = static_cast<uint16_t>(start);
                        }
                    }
                }
                prev_max = island_max;
                prev_crossings = total_crossings;
            }

            size_t end = regular_count;
            out.island_begin[islands] = static_cast<uint16_t>(regular_count);
            for (size_t k = islands; k >= 1; --k) {
                const uint16_t start = choice[k][end];
                out.island_begin[k - 1] = start;
                end = start;
            }
            return true;
        }


        template<size_t MaxBlocksParam, size_t MaxWorkers = DEFAULT_MAX_WORKERS>
        class WorkerQueueScheduler {
            using block_index_t = uint8_t;

            static_assert(MaxBlocksParam >= 1, "Must support at least one block");
            static_assert(MaxWorkers >= 1, "Must support at least one worker");
            static_assert(MaxBlocksParam <= (std::numeric_limits<block_index_t>::max)(),
                          "MaxBlocksParam exceeds block_index_t capacity");

            struct alignas(platform::cache_line_size) WorkerQueue {
                std::array<block_index_t, MaxBlocksParam> blocks;
                uint32_t count = 0;
                uint32_t current = 0;

                bool get_block(size_t& block_idx_out) {
                    if (current < count) {
                        block_idx_out = blocks[current++];
                        return true;
                    }
                    return false;
                }

                void reset() {
                    current = 0;
                }
            };

            static_assert(sizeof(WorkerQueue) <= platform::cache_line_size * 4,
                          "WorkerQueue is too large, consider reducing MaxBlocksParam");

            static constexpr size_t kNoOwner = (std::numeric_limits<size_t>::max)();

            std::array<WorkerQueue, MaxWorkers> queues;
            std::array<size_t, MaxBlocksParam> block_owner;

        public:
            void initialize(const block_index_t* block_ids, size_t block_id_count, size_t workers) {
                for (auto& q : queues) {
                    q.count = 0;
                    q.current = 0;
                }
                block_owner.fill(kNoOwner);

                const size_t per = (block_id_count + workers - 1) / workers;
                size_t idx = 0;
                for (size_t w = 0; w < workers && idx < block_id_count; ++w) {
                    auto& q = queues[w];
                    for (size_t k = 0; k < per && idx < block_id_count; ++k, ++idx) {
                        block_index_t bidx = block_ids[idx];
                        q.blocks[q.count++] = bidx;
                        block_owner[bidx] = w;
                    }
                }
            }

            void initialize_islands(const block_index_t* block_ids, const uint16_t* island_begin, size_t island_count) {
                for (auto& q : queues) {
                    q.count = 0;
                    q.current = 0;
                }
                block_owner.fill(kNoOwner);

                for (size_t w = 0; w < island_count && w < MaxWorkers; ++w) {
                    auto& q = queues[w];
                    for (uint16_t k = island_begin[w]; k < island_begin[w + 1]; ++k) {
                        block_index_t bidx = block_ids[k];
                        q.blocks[q.count++] = bidx;
                        block_owner[bidx] = w;
                    }
                }
            }

            bool get_next_block(size_t worker_id, size_t& block_idx_out) {
                return queues[worker_id].get_block(block_idx_out);
            }

            void reset_pass(size_t worker_id) {
                queues[worker_id].reset();
            }

            bool is_block_owner(size_t worker_id, size_t block_idx) const {
                return block_idx < block_owner.size() && block_owner[block_idx] == worker_id;
            }
        };

    }
    }
}

#pragma once

#include "../cler_scheduler_config.hpp"
#include <array>
#include <algorithm>
#include <cstddef>
#include <cstdint>

namespace cler {


    namespace sched {
    namespace detail {

        template<size_t MaxBlocks>
        void topo_sort_blocks(const Edge* edges, size_t edge_count,
                              const uint8_t* ids, size_t count,
                              std::array<uint8_t, MaxBlocks>& out) {
            std::array<uint16_t, MaxBlocks> indegree{};
            std::array<uint8_t, MaxBlocks> in_set{};
            std::array<uint8_t, MaxBlocks> emitted{};

            for (size_t i = 0; i < count; ++i) in_set[ids[i]] = 1;
            for (size_t e = 0; e < edge_count; ++e) {
                const Edge& edge = edges[e];
                if (edge.producer == edge.consumer) continue;
                if (in_set[edge.producer] && in_set[edge.consumer]) ++indegree[edge.consumer];
            }

            size_t emitted_count = 0;
            bool progressed = true;
            while (progressed) {
                progressed = false;
                for (size_t i = 0; i < count; ++i) {
                    const uint8_t b = ids[i];
                    if (emitted[b] || indegree[b] != 0) continue;
                    emitted[b] = 1;
                    out[emitted_count++] = b;
                    progressed = true;
                    for (size_t e = 0; e < edge_count; ++e) {
                        const Edge& edge = edges[e];
                        if (edge.producer != b || edge.producer == edge.consumer) continue;
                        if (in_set[edge.consumer] && !emitted[edge.consumer]) --indegree[edge.consumer];
                    }
                }
            }
            for (size_t i = 0; i < count; ++i) {
                if (!emitted[ids[i]]) out[emitted_count++] = ids[i];
            }
        }

        template<size_t MaxBlocks>
        void count_cut_crossings(const Edge* edges, size_t edge_count,
                                 const std::array<uint8_t, MaxBlocks>& order, size_t count,
                                 std::array<uint16_t, MaxBlocks>& crossings) {
            std::array<uint16_t, MaxBlocks> position{};
            std::array<uint8_t, MaxBlocks> in_order{};
            for (size_t i = 0; i < count; ++i) {
                position[order[i]] = static_cast<uint16_t>(i);
                in_order[order[i]] = 1;
            }

            for (size_t e = 0; e < edge_count; ++e) {
                const Edge& edge = edges[e];
                if (!in_order[edge.producer] || !in_order[edge.consumer]) continue;
                const uint16_t producer_pos = position[edge.producer];
                const uint16_t consumer_pos = position[edge.consumer];
                const uint16_t low = (std::min)(producer_pos, consumer_pos);
                const uint16_t high = (std::max)(producer_pos, consumer_pos);
                for (uint16_t cut = static_cast<uint16_t>(low + 1); cut <= high; ++cut) {
                    ++crossings[cut];
                }
            }
        }

    }
    }
}

