#pragma once

#include <cstdlib>

#include "cler.hpp"
#include "cler_task_policy_base.hpp"
#include <thread>
#include <chrono>
#include <algorithm>
#include <atomic>
#include <cstdint>
#include <cstdio>
#ifdef __linux__
#include <sys/prctl.h>
#include <sys/syscall.h>
#include <linux/futex.h>
#include <unistd.h>
#include <ctime>
#include <climits>
#else
#include <mutex>
#include <condition_variable>
#endif

namespace cler {

struct DesktopTaskPolicy : TaskPolicyBase<DesktopTaskPolicy> {
    using task_type = std::thread;

    template <typename F>
    static task_type create_task(F&& func) {
        return std::thread(std::forward<F>(func));
    }

    static void join_task(task_type& t) {
        if (t.joinable()) t.join();
    }

    static void yield() {
        std::this_thread::yield();
    }

    static void sleep_us(size_t us) {
        std::this_thread::sleep_for(std::chrono::microseconds(us));
    }

    static inline void relax() {
        platform::spin_wait(64);
    }

    static constexpr size_t backoff_spin_steps = 8;
    static constexpr size_t backoff_yield_steps = 16;
    static constexpr size_t backoff_initial_sleep_us = 1;
    static constexpr size_t backoff_max_sleep_us = 1000;
    static constexpr size_t backoff_max_shift = 10;

    static inline void backoff(BackoffState& state) {
        if (state.step < backoff_spin_steps) {
            platform::spin_wait(64);
        } else if (state.step < backoff_yield_steps) {
            std::this_thread::yield();
        } else {
            size_t shift = (std::min)(state.step - backoff_yield_steps, backoff_max_shift);
            size_t sleep_us_value = (std::min)(backoff_initial_sleep_us << shift, backoff_max_sleep_us);
            sleep_us(sleep_us_value);
        }
        ++state.step;
    }

    static inline void backoff_reset(BackoffState& state) {
        state.step = 0;
    }

    static inline bool pin_to_core(size_t worker_id) {
        return platform::set_thread_affinity(worker_id);
    }

    static inline void warn_unresolved_edge(const char* producer_name, const void* address) {
        std::fprintf(stderr,
            "cler: unresolved output edge from block '%s' at %p (no consumer found; "
            "edge derivation matches channels stored inside the consuming block's object). "
            "PinnedIslands will fall back to a contiguous partition.\n",
            producer_name, address);
    }

    [[noreturn]] static inline void fatal(const char* msg, const char* detail) {
        std::fprintf(stderr, "cler: fatal: %s%s%s\n", msg,
                     (detail && *detail) ? ": " : "", (detail && *detail) ? detail : "");
        std::abort();
    }

    static inline void report_partition_block(size_t island, size_t position, const char* name,
                                              double cpu_ns_per_second) {
        std::fprintf(stderr, "cler: partition island %zu pos %zu %-16s %.3f cores\n",
                     island, position, name, cpu_ns_per_second / 1e9);
    }

    static constexpr size_t park_timeout_us = 1000;

    static_assert(sizeof(std::atomic<uint32_t>) == sizeof(uint32_t),
                  "park/unpark require a lock-free uint32_t-sized atomic");

#ifdef __linux__
    static inline uint32_t* futex_word(const std::atomic<uint32_t>& sleep_epoch) {
        return const_cast<uint32_t*>(reinterpret_cast<const uint32_t*>(&sleep_epoch));
    }

    static inline void park(const std::atomic<uint32_t>& sleep_epoch, uint32_t expected) {
        struct timespec timeout{0, static_cast<long>(park_timeout_us * 1000)};
        syscall(SYS_futex, futex_word(sleep_epoch), FUTEX_WAIT_PRIVATE, expected, &timeout, nullptr, 0);
    }

    static inline void unpark(std::atomic<uint32_t>& sleep_epoch) {
        syscall(SYS_futex, futex_word(sleep_epoch), FUTEX_WAKE_PRIVATE, INT_MAX, nullptr, nullptr, 0);
    }
#else
    struct ParkSlot {
        std::mutex mutex;
        std::condition_variable cv;
    };

    static inline ParkSlot& park_slot(const std::atomic<uint32_t>& sleep_epoch) {
        static ParkSlot slots[16];
        return slots[(reinterpret_cast<uintptr_t>(&sleep_epoch) / 64) % 16];
    }

    static inline void park(const std::atomic<uint32_t>& sleep_epoch, uint32_t expected) {
        ParkSlot& slot = park_slot(sleep_epoch);
        std::unique_lock<std::mutex> lock(slot.mutex);
        if (sleep_epoch.load(std::memory_order_acquire) != expected) return;
        slot.cv.wait_for(lock, std::chrono::microseconds(park_timeout_us));
    }

    static inline void unpark(std::atomic<uint32_t>& sleep_epoch) {
        ParkSlot& slot = park_slot(sleep_epoch);
        std::lock_guard<std::mutex> lock(slot.mutex);
        slot.cv.notify_all();
    }
#endif

    static inline void configure_thread_for_low_latency_sleep() {
#ifdef __linux__
        prctl(PR_SET_TIMERSLACK, 1);
#endif
    }
};


template<typename... Runners>
auto make_desktop_flowgraph(Runners&&... runners) {
    return cler::FlowGraph<cler::DesktopTaskPolicy, std::decay_t<Runners>...>(
        std::forward<Runners>(runners)...
    );
}

template<typename... BlockRunners>
using DesktopFlowGraph = FlowGraph<DesktopTaskPolicy, BlockRunners...>;

} // namespace cler

include/task_policies/cler_threadx_tpoli:
#pragma once

#include "cler_task_policy_base.hpp"
// Include ThreadX headers
#include "tx_api.h"

namespace cler {

#ifndef CLER_THREADX_STACK_SIZE
#define CLER_THREADX_STACK_SIZE 4096
#endif

#ifndef CLER_THREADX_PRIORITY
#define CLER_THREADX_PRIORITY 16
#endif

#ifndef CLER_THREADX_TIME_SLICE
#define CLER_THREADX_TIME_SLICE TX_NO_TIME_SLICE
#endif

#ifndef CLER_THREADX_PREEMPT_THRESHOLD
#define CLER_THREADX_PREEMPT_THRESHOLD 16
#endif

struct ThreadXTaskPolicy : TaskPolicyBase<ThreadXTaskPolicy> {
    // Import default implementations from base
    using TaskPolicyBase<ThreadXTaskPolicy>::relax;
    using TaskPolicyBase<ThreadXTaskPolicy>::pin_to_core;

    // Structure to hold task data
    struct TaskData {
        void* callable;
        void (*invoke)(void*);
        void (*destroy)(void*);
        TX_SEMAPHORE* completion_sem;
        volatile bool task_completed;
    };

    struct TaskWrapper {
        TX_THREAD thread;
        TX_SEMAPHORE completion_sem;
        TaskData* task_data;
        UCHAR* stack_memory;
        volatile bool task_completed;
        bool is_valid;
    };

    using task_type = TaskWrapper;

    // Template helper to generate invoke and destroy functions
    template<typename Func>
    struct TaskHelper {
        static void invoke(void* callable) {
            (*static_cast<Func*>(callable))();
        }

        static void destroy(void* callable) {
            delete static_cast<Func*>(callable);
        }
    };

    template<typename Func>
    static task_type create_task(Func&& f) {
        task_type wrapper{};
        wrapper.is_valid = false;
        wrapper.task_completed = false;
        wrapper.task_data = nullptr;

        // Allocate stack memory
        wrapper.stack_memory = new UCHAR[CLER_THREADX_STACK_SIZE];
        if (!wrapper.stack_memory) {
            return wrapper; // Failed allocation
        }

        // Create completion semaphore
        static char sem_name[] = "ClerCompletionSem";
        UINT status = tx_semaphore_create(
            &wrapper.completion_sem,
            sem_name,
            0  // Initial count
        );

        if (status != TX_SUCCESS) {
            delete[] wrapper.stack_memory;
            return wrapper;
        }

        // Allocate task data
        using FuncType = typename std::decay<Func>::type;
        auto* task_data = new TaskData;
        task_data->callable = new FuncType(std::forward<Func>(f));
        task_data->invoke = &TaskHelper<FuncType>::invoke;
        task_data->destroy = &TaskHelper<FuncType>::destroy;
        task_data->completion_sem = &wrapper.completion_sem;
        task_data->task_completed = false;
        wrapper.task_data = task_data;

        // Create ThreadX thread
        static char thread_name[] = "ClerThread";
        status = tx_thread_create(
            &wrapper.thread,                    // Thread control block
            thread_name,                        // Thread name
            thread_entry_point,                 // Thread entry function
            (ULONG)task_data,                  // Thread input
            wrapper.stack_memory,               // Stack start
            CLER_THREADX_STACK_SIZE,           // Stack size
            CLER_THREADX_PRIORITY,             // Priority
            CLER_THREADX_PREEMPT_THRESHOLD,    // Preemption threshold
            CLER_THREADX_TIME_SLICE,           // Time slice
            TX_AUTO_START                       // Auto start
        );

        if (status != TX_SUCCESS) {
            tx_semaphore_delete(&wrapper.completion_sem);
            task_data->destroy(task_data->callable);
            delete task_data;
            delete[] wrapper.stack_memory;
            wrapper.task_data = nullptr;
            return wrapper;
        }

        wrapper.is_valid = true;
        return wrapper;
    }

    static void join_task(task_type& wrapper) {
        if (wrapper.is_valid && wrapper.task_data && !wrapper.task_completed) {
            // Wait for thread completion
            tx_semaphore_get(&wrapper.completion_sem, TX_WAIT_FOREVER);

            // Clean up thread
            tx_thread_terminate(&wrapper.thread);
            tx_thread_delete(&wrapper.thread);
            tx_semaphore_delete(&wrapper.completion_sem);

            // Clean up memory
            wrapper.task_data->destroy(wrapper.task_data->callable);
            delete wrapper.task_data;
            delete[] wrapper.stack_memory;

            wrapper.task_data = nullptr;
            wrapper.stack_memory = nullptr;
            wrapper.is_valid = false;
            wrapper.task_completed = true;
        }
    }

    static void yield() {
        tx_thread_relinquish();
    }

    static void sleep_us(size_t microseconds) {
        // Convert microseconds to timer ticks
        // ThreadX timer ticks are typically milliseconds
        ULONG ticks = (microseconds + 999) / 1000; // Round up to ms
        if (ticks == 0) ticks = 1; // Minimum delay
        tx_thread_sleep(ticks);
    }

private:
    // Thread entry point for ThreadX
    static void thread_entry_point(ULONG parameters) {
        auto* data = reinterpret_cast<TaskData*>(parameters);

        // Execute the stored function
        if (data->callable && data->invoke) {
            data->invoke(data->callable);
        }

        // Signal completion
        tx_semaphore_put(data->completion_sem);

        // Thread will be cleaned up by join_task
    }
};

// Forward declaration
template<typename TaskPolicy, typename... BlockRunners>
class FlowGraph;

// Convenient factory function for ThreadX-based FlowGraph
template<typename... Runners>
auto make_threadx_flowgraph(Runners&&... runners) {
    return cler::FlowGraph<cler::ThreadXTaskPolicy, std::decay_t<Runners>...>(
        std::forward<Runners>(runners)...
    );
}

// Convenient alias for ThreadX-based FlowGraph
template<typename... BlockRunners>
using ThreadXFlowGraph = FlowGraph<ThreadXTaskPolicy, BlockRunners...>;

} // namespace cler

