#else
#  define LIQUID_FILENAME __FILE__
#endif

//
// Make sure the version and version number macros weren't defined by
// some previously included header file.
//
#ifdef LIQUID_VERSION
#  undef LIQUID_VERSION
#endif
#ifdef LIQUID_VERSION_NUMBER
#  undef LIQUID_VERSION_NUMBER
#endif

// Compile-time version numbers

// macros for expanding version numbers to string literals
#define LIQUID_VERSION_STR_EX(num) #num
#define LIQUID_VERSION_STR(num) LIQUID_VERSION_STR_EX(num)

#define LIQUID_VERSION_MAJOR    1
#define LIQUID_VERSION_MINOR    8
#define LIQUID_VERSION_PATCH    2
#define LIQUID_VERSION_DEV      0

// final version string is constructed by concatenating individual string versions
#define LIQUID_VERSION \
    LIQUID_VERSION_STR(LIQUID_VERSION_MAJOR) "." \
    LIQUID_VERSION_STR(LIQUID_VERSION_MINOR) "." \
    LIQUID_VERSION_STR(LIQUID_VERSION_PATCH)

// final version number is constructed from major, minor, patch
#define LIQUID_VERSION_NUMBER ( \
    (uint32_t) ( \
    (LIQUID_VERSION_MAJOR << 16) | \
    (LIQUID_VERSION_MINOR <<  8) | \
    (LIQUID_VERSION_PATCH      )))

//
// Run-time library version numbers
//
extern const char liquid_version[];
const char * liquid_libversion(void);
int liquid_libversion_number(void);

// run-time library validation
#define LIQUID_VALIDATE_LIBVERSION                                          \
  if (LIQUID_VERSION_NUMBER != liquid_libversion_number()) {                \
    fprintf(stderr,"%s:%u: ", LIQUID_FILENAME,__LINE__);                    \
    fprintf(stderr,"error: invalid liquid runtime library\n");              \
    fprintf(stderr,"  header version  : %d\n", LIQUID_VERSION_NUMBER);      \
    fprintf(stderr,"  library version : %d\n", liquid_libversion_number()); \
    exit(1);                                                                \
  }                                                                         \

// structure to define instruction set architecture options/availability
struct liquid_cpuinfo_s
{
    // PPC architecture
    bool altivec;

    // ARM architecture
    bool neon;

    // x86 architecture
    bool mmx;       // multi-media extension (1997)
    bool sse;       // streaming SIMD extensions (1999)
    bool sse2;      // SSE version 2 (2000)
    bool sse3;      // SSE version 3 (2004)
    bool ssse3;     // Supplemental SSE3 (2006)
    bool sse41;     // SSE version 4.1 (2007)
    bool sse42;     // SSE version 4.2 (2008)
    bool avx;       // advanced vector extensions (2011)
    bool fma3;      // fused multiply-add (2013)
    bool avx2;      // AVX version 2 (2013)
    bool avx512;    // AVX-512 (2016)
    bool amx;       // advanced matrix extensions (2023)
    bool amx101;    // AMX version 10.1 (2024)
    bool amx102;    // AMX version 10.2 (2026)
};
typedef struct liquid_cpuinfo_s * liquid_cpuinfo;

// check which instruction extensions are supported on this system
int liquid_get_cpuinfo(liquid_cpuinfo _cpu);

// structure to define system information
struct liquid_sysinfo_s
{
