                  float                    _ap,
                  float                    _as,
                  float *                  _b,
                  float *                  _a);

// compute analog zeros, poles, gain for specific filter types
int butter_azpkf(unsigned int           _n,
                 liquid_float_complex * _za,
                 liquid_float_complex * _pa,
                 liquid_float_complex * _ka);
int cheby1_azpkf(unsigned int           _n,
