int IIRHILB(_c2r_execute_block)(IIRHILB()    _q,                            \
                                TC *         _x,                            \
                                unsigned int _n,                            \
                                T *          _y);                           \
                                                                            \
/* Execute Hilbert transform decimator (real to complex)                */  \
