int FIRDECIM(_destroy)(FIRDECIM() _q);                                      \
                                                                            \
/* Print decimator object properties to stdout                          */  \
int FIRDECIM(_print)(FIRDECIM() _q);                                        \
                                                                            \
/* Reset decimator object internal state                                */  \
