/*  _scale  : scaling factor to apply to each output sample             */  \
int FIRDECIM(_get_scale)(FIRDECIM() _q,                                     \
                         TC *       _scale);                                \
                                                                            \
/* Compute complex frequency response \(H\) of decimator on prototype   */  \
