/*  _q              : resamp object                                     */  \
/*  _x              : input buffer, [size: _nx x 1]                     */  \
/*  _nx             : input buffer                                      */  \
/*  _y              : output sample array (pointer)                     */  \
/*  _ny             : number of samples written to _y                   */  \
int RESAMP(_execute_block)(RESAMP()       _q,                               \
                           TI *           _x,                               \
                           unsigned int   _nx,                              \
                           TO *           _y,                               \
                           unsigned int * _ny);                             \

